def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'

    opp_moves = [o for _, o in history]
    my_moves = [m for m, _ in history]
    last_me, last_opp = history[-1]

    # Counts
    opp_def = 0
    my_def = 0
    cc = cd = dc = dd = 0
    for i in range(n):
        m = my_moves[i]
        o = opp_moves[i]
        if m == 'D':
            my_def += 1
        if o == 'D':
            opp_def += 1
        if m == 'C':
            if o == 'C':
                cc += 1
            else:
                cd += 1
        else:
            if o == 'C':
                dc += 1
            else:
                dd += 1

    opp_coop_rate = (n - opp_def) / float(n)

    # Windowed opponent defections
    def opp_def_last(k):
        c = 0
        start = n - k
        if start < 0:
            start = 0
        for i in range(start, n):
            if opp_moves[i] == 'D':
                c += 1
        return c

    def my_def_last(k):
        c = 0
        start = n - k
        if start < 0:
            start = 0
        for i in range(start, n):
            if my_moves[i] == 'D':
                c += 1
        return c

    # Endgame exploitation: against cooperative opponents, defect at the very end.
    if n >= 96:
        if opp_coop_rate >= 0.6:
            return 'D'
        if last_opp == 'D':
            return 'D'
        return 'C'

    # Forgiving opening: probe cooperation for the first few rounds.
    if n < 4:
        if last_opp == 'D' and opp_def_last(2) >= 2:
            return 'D'
        return 'C'

    # If opponent has been almost perfectly cooperative, cooperate.
    if opp_def == 0:
        # Rare probe to keep them honest, but not too often near the end.
        if n > 12 and n < 85 and n % 17 == 0:
            return 'D'
        return 'C'

    # If opponent is essentially always defecting, defect.
    if opp_coop_rate <= 0.15:
        return 'D'

    # Strong recent defection cluster -> retaliate.
    if opp_def_last(3) >= 3:
        return 'D'
    if opp_def_last(5) >= 4:
        return 'D'

    # Short window: recent opponent heavily defecting.
    if n >= 15:
        r10 = opp_def_last(10)
        if r10 >= 7:
            return 'D'

    # Tit-for-tat-like core with limited forgiveness.
    if last_opp == 'D':
        # We were caught cooperating: punish, but sometimes forgive if opponent mostly cooperates.
        if last_me == 'C':
            if opp_coop_rate >= 0.8 and opp_def_last(5) <= 1 and n < 90:
                return 'C'
            return 'D'
        else:
            # Mutual defection: continue defecting briefly to discourage exploitation,
            # but return to cooperation fairly soon to avoid long DD lock-in.
            # Measure consecutive defections between both players.
            consec_dd = 0
            i = n - 1
            while i >= 0 and my_moves[i] == 'D' and opp_moves[i] == 'D':
                consec_dd += 1
                i -= 1
            if consec_dd >= 3:
                # Try to break out of DD.
                if n < 90:
                    return 'C'
                return 'D'
            # First mutual defection: one more defection, then likely cooperate.
            if consec_dd >= 2 and n < 90 and rng.random() < 0.5:
                return 'C'
            return 'D'

    # last_opp == 'C'
    # Opponent just cooperated. Cooperate unless we've been exploited a lot.
    if n >= 20:
        opp_def_rate_recent = opp_def_last(20) / 20.0
        my_def_rate_recent = my_def_last(20) / 20.0
        # If opponent has been systematically defecting more than us, be cautious.
        if opp_def_rate_recent > 0.4 and my_def_rate_recent < 0.2:
            # They might be exploiting our cooperativeness; defect occasionally.
            if n < 90:
                if rng.random() < 0.5:
                    return 'D'
                return 'C'
            return 'D'

    # If we have been defecting recently more than the opponent, occasionally cooperate
    # to signal willingness to restore CC.
    if my_def_last(5) >= 3 and opp_def_last(5) <= 1:
        if n < 90 and rng.random() < 0.3:
            return 'D'
        return 'C'

    return 'C'
